import {getProfile} from './profile-store.js?v=30';
export function chooseSharing(t){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='sharing-dialog';d.setAttribute('aria-labelledby','sharing-title');d.innerHTML=`<header><h2 id="sharing-title">${t('保存你的设计','Save your design')}</h2><button data-cancel aria-label="${t('关闭','Close')}">×</button></header><p>${t('作品会保存到“我的设计”。你也可以自愿分享到作品中心。','Your work will be saved to My designs. Sharing it with the community is optional.')}</p><label class="sharing-consent"><input type="checkbox" id="share-consent"><span>${t('我已阅读隐私与分享说明，同意将此作品公开到作品中心，供他人参考、点赞、复用及打印。','I have read the privacy and sharing notice and agree to publish this design in Works center for others to view, like, reuse and print.')}</span></label><details class="sharing-notice"><summary>${t('隐私与分享说明','Privacy & sharing notice')}</summary><p>${t('勾选后，当前作品图片、作者头像、昵称和机型标签将公开。请确认你有权分享图片和文字，且不包含不希望公开的个人信息。不勾选仍可保存为私人草稿；已分享作品可在自己的作品详情中取消公开。','If selected, your current artwork, author avatar, nickname and phone-model tag will be public. Only share images and text you have permission to use, without personal information you wish to keep private. Leave unchecked to save privately. You can withdraw a shared design from its details page.')}</p></details><div class="sharing-actions"><button class="secondary" data-cancel>${t('取消','Cancel')}</button><button class="primary" data-save>${t('保存设计','Save design')}</button></div>`;let result=null;d.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>d.close());d.querySelector('[data-save]').onclick=()=>{const share=d.querySelector('input').checked;result={published:share,sharingConsentAt:share?Date.now():null,author:getProfile()?.nickname||t('POPOMO 创作者','POPOMO creator'),authorAvatar:getProfile()?.avatar||'./assets/avatars/avatar-1-v30.svg'};d.close();};d.addEventListener('close',()=>{d.remove();resolve(result);},{once:true});document.body.append(d);d.showModal();});}
